<?php $total=0; foreach($shop_items as $item) $total += $item->price*$item->quantity; ?>
<div class="va-shop-page"><div class="va-static-hero"><div><span>Secure purchase</span><h1>Checkout</h1></div><nav><a href="<?= base_url() ?>">Home</a> / Checkout</nav></div><?php if(empty($shop_items)): ?><div class="va-shop-empty"><i class="bi bi-cart-x"></i><h2>Your cart is empty</h2><a class="btn va-why-button" href="<?= base_url('accessories') ?>">Shop Now</a></div><?php else: ?><div class="va-checkout-layout"><form class="va-checkout-form" action="<?= html_escape($whatsapp_url) ?>" target="_blank"><h2>Billing details</h2><div class="va-checkout-two"><label>First name *<input required></label><label>Last name<input></label></div><label>Phone *<input required></label><label>Address *<input required></label><label>City / State *<input required></label><label>Email address *<input type="email" required></label><label>Order notes<textarea rows="4"></textarea></label></form><aside class="va-order-summary"><h2>Your order</h2><?php foreach($shop_items as $item): ?><p><span><?= html_escape($item->name) ?> × <?= $item->quantity ?></span><strong>&#8377; <?= number_format($item->price*$item->quantity) ?></strong></p><?php endforeach; ?><p><span>Shipping</span><b>Free shipping</b></p><p class="va-order-total"><span>Total</span><strong>&#8377; <?= number_format($total) ?></strong></p><div class="va-payment-choice"><b>Cash on delivery</b><small>Pay when your order is delivered.</small></div><button form="" class="btn va-why-button w-100" onclick="window.open('<?= html_escape($whatsapp_url) ?>','_blank')">Place Order</button></aside></div><?php endif; ?></div>
